const BANK_BY_LEVEL: Record<string, any[]> = { A1: BANK, A2: A2_BANK };
function competitionBankForLevel(level: string) { return BANK_BY_LEVEL[level] || BANK; }
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
class ApiError extends Error {
  status: number; code: string;
  constructor(message: string, status = 400, code = "bad_request") { super(message); this.status = status; this.code = code; }
}
function json(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });
}
function cleanName(value: unknown, fallback = "متعلّم") { const name = String(value || fallback).trim().slice(0, 50); return name || "متعلّم"; }
async function getIdentity(req: Request) {
  const auth = req.headers.get("Authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : "";
  if (!token) throw new ApiError("سجّل الدخول بحساب التلميذ أولاً.", 401, "unauthenticated");
  try {
    const { payload } = await jwtVerify(token, firebaseJwks, {
      issuer: `https://securetoken.google.com/${FIREBASE_PROJECT_ID}`,
      audience: FIREBASE_PROJECT_ID, clockTolerance: 5,
    });
    if (!payload.sub || typeof payload.sub !== "string") throw new Error("missing uid");
    return { uid: payload.sub, token, claims: payload };
  } catch (_error) { throw new ApiError("جلسة Firebase غير صالحة أو انتهت. سجّل الدخول من جديد.", 401, "invalid_token"); }
}
async function firebaseRead(path: string, token: string) {
  const response = await fetch(`${FIREBASE_DATABASE_URL}/${path}.json?auth=${encodeURIComponent(token)}`);
  if (!response.ok) throw new ApiError(`تعذّر قراءة بيانات التلميذ من Firebase (${response.status}).`, 403, "firebase_read_failed");
  return await response.json();
}
async function getStudentProfile(uid: string, token: string) {
  const profile = await firebaseRead(`deutschA1/users/${encodeURIComponent(uid)}`, token);
  if (!profile || profile.active === false || profile._systemPlaceholder === true) throw new ApiError("حساب التلميذ غير نشط أو غير موجود في Firebase.", 403, "student_not_allowed");
  return profile;
}
// Check the same course permissions as the group editor, using the current Firebase data.
// Never silently ignore a failed group read or let an individual override reopen a locked lesson.
function competitionLevelPermitted(profile: any, group: any, level: string) {
  return Boolean(profile.groupId && group && group.competitionLevelAccess?.[level] === true && group.levelAccess?.[level] !== false && profile.levelAccess?.[level] !== false);
}
function competitionLessonPermitted(profile: any, group: any, index: number, level: string) {
  if (!competitionLevelPermitted(profile, group, level) || !["A1", "A2"].includes(level)) return false;
  if (!Number.isInteger(index) || index < 0 || !competitionBankForLevel(level)[index]?.questions?.length) return false;
  const key = String(level === "A1" && index === 10 ? 7 : index + 1);
  const perLevel = group.lessonAccessByLevel?.[level];
  const groupAccess = perLevel && typeof perLevel === "object" ? perLevel : level === "A1" ? group.lessonAccess : null;
  const ownByLevel = profile.lessonAccessByLevel?.[level];
  const ownAccess = Object.prototype.hasOwnProperty.call(ownByLevel || {}, key)
    ? ownByLevel[key] : level === "A1" ? profile.lessonAccess?.[key] : undefined;
  return groupAccess?.[key] !== false && ownAccess !== false;
}
async function assertLessonAccess(profile: any, token: string, lessonIndices: number[], level = "A1") {
  if (!profile.groupId) throw new ApiError("خاصك تكون منضم لمجموعة باش تشارك فالمنافسة.", 403, "competition_group_required");
  const group = await firebaseRead(`deutschA1/groups/${encodeURIComponent(String(profile.groupId))}`, token);
  if (!competitionLevelPermitted(profile, group, level)) throw new ApiError(`المستوى ${level} مقفول من الإدارة.`, 403, "competition_level_access_denied");
  if (lessonIndices.some(index => !competitionLessonPermitted(profile, group, index, level))) {
    throw new ApiError("كاين درس مقفول حسب صلاحيات المجموعة أو التلميذ.", 403, "lesson_access_denied");
  }
}
function normalizeCompetitionLevel(value: unknown) {
  const level = String(value || "A1").toUpperCase();
  if (!["A1", "A2", "B1", "B2"].includes(level)) throw new ApiError("مستوى المنافسة غير صالح.", 400, "invalid_competition_level");
  return level;
}
async function assertCompetitionLevelAccess(profile: any, token: string, level: string) {
  if (!profile.groupId) throw new ApiError("خاصك تكون منضم لمجموعة باش تشارك فالمنافسة.", 403, "competition_group_required");
  const group = await firebaseRead(`deutschA1/groups/${encodeURIComponent(String(profile.groupId))}`, token);
  if (!group || group.competitionLevelAccess?.[level] !== true || group.levelAccess?.[level] === false || profile.levelAccess?.[level] === false) {
    throw new ApiError(`الإدارة ما فتحتش المستوى ${level} للمنافسة فالمجموعة ديالك.`, 403, "competition_level_access_denied");
  }
  // A1 and A2 have separate source-derived banks. B1/B2 stay unavailable until their own banks exist.
  if (!["A1", "A2"].includes(level)) {
    throw new ApiError(`المستوى ${level} مفتوح من الإدارة، ولكن بنك أسئلة المنافسة ديالو مازال ما تضافش.`, 409, "competition_level_content_unavailable");
  }
}
function shuffle<T>(items: T[]): T[] {
  const output = items.slice();
  for (let i = output.length - 1; i > 0; i--) {
    const j = crypto.getRandomValues(new Uint32Array(1))[0] % (i + 1);
    [output[i], output[j]] = [output[j], output[i]];
  }
  return output;
}
function selectedCompetitionCategories(lessonIndices: number[], testTypes: unknown, level = "A1"): Map<number, Set<string>> {
  const out = new Map<number, Set<string>>();
  const bank = competitionBankForLevel(level);
  if (testTypes === undefined || testTypes === null) return out; // existing clients remain compatible
  if (!testTypes || typeof testTypes !== "object" || Array.isArray(testTypes)) {
    throw new ApiError("اختيار أنواع التمارين غير صالح.", 400, "invalid_test_types");
  }
  const selected = testTypes as Record<string, unknown>;
  for (const lessonIndex of lessonIndices) {
    const validCategories: string[] = [...new Set<string>((bank[lessonIndex]?.questions || []).map((q: any) => String(q.category || "Test")))];
    const typeIndices = selected[String(lessonIndex)];
    if (!Array.isArray(typeIndices) || typeIndices.length < 1) {
      throw new ApiError("اختار نوع تمرين واحد على الأقل لكل درس.", 400, "missing_test_type");
    }
    const allowed = new Set<string>();
    for (const rawIndex of typeIndices) {
      const index = Number(rawIndex);
      if (!Number.isInteger(index) || index < 0 || index >= validCategories.length) {
        throw new ApiError("نوع تمرين غير صالح.", 400, "unknown_test_type");
      }
      allowed.add(validCategories[index]);
    }
    out.set(lessonIndex, allowed);
  }
  return out;
}

// Arabic hints from the existing Flohmarkt Test, Übung 4 (source: pages/Test/lektion-9-test.html).
const ORIGINAL_EXERCISE_NOTES: Record<string, string> = {
  "8|Auf dem ___ gibt es viele Sachen.": "يوجد الكثير من الأشياء في سوق السلع المستعملة.",
  "8|Ich suche eine ___.": "أنا أبحث عن حقيبة يد.",
  "8|Wie viel ___ das Buch?": "كم ثمن الكتاب؟",
  "8|Der Verkäufer ___ alte Bücher.": "البائع يبيع كتباً قديمة.",
  "8|Die Schuhe sind sehr ___.": "الأحذية رخيصة جداً.",
  "8|Ich möchte die Kamera ___.": "أريد شراء الكاميرا.",
  "8|Die Besucher ___ schöne Sachen.": "الزوار يبحثون عن أشياء جميلة.",
  "8|Die Tasche ist nicht teuer. Sie ist ___.": "الحقيبة ليست غالية، إنها رخيصة."
};

function buildQuiz(level: string, lessonIndices: number[], requestedCount: number, testTypes?: unknown, wholeExercises = false) {
  const bank = competitionBankForLevel(level);
  const selectedCategories = selectedCompetitionCategories(lessonIndices, testTypes, level);
  // A1/A2 banks contain source-derived, auto-gradable course and practice exercises.
  // The browser receives the answer key only for its submitted answer.
  const pool: any[] = [];
  const seen = new Set<string>();
  for (const lessonIndex of lessonIndices) {
    const lesson = bank[lessonIndex];
    if (!lesson || !Array.isArray(lesson.questions)) continue;
    for (const source of lesson.questions) {
      const category = String(source.category || "Test");
      if (selectedCategories.has(lessonIndex) && !selectedCategories.get(lessonIndex)!.has(category)) continue;
      const prompt = String(source.prompt || "").trim();
      const options = Array.isArray(source.options) ? source.options.map(String) : [];
      const correctIndex = Number(source.correctIndex);
      if (!prompt || options.length < 2 || options.length > 4 ||
          !Number.isInteger(correctIndex) || correctIndex < 0 || correctIndex >= options.length ||
          new Set(options).size !== options.length) continue;
      const key = `${lessonIndex}|${category}|${prompt}|${options[correctIndex]}`;
      if (seen.has(key)) continue;
      seen.add(key);
      pool.push({
        prompt, options, correctIndex, lessonIndex,
        lessonName: lesson.name, category,
        note: source.note || (level === "A1" ? ORIGINAL_EXERCISE_NOTES[`${lessonIndex}|${prompt}`] || "" : ""),
        exerciseType: source.exerciseType || "choice",
        answerMode: source.answerMode || "choice",
        exerciseTitle: source.exerciseTitle || "",
        exerciseInstruction: source.exerciseInstruction || "",
        exerciseNumber: source.exerciseNumber || null,
        scramble: source.scramble || "",
        letters: Array.isArray(source.letters) ? source.letters : [],
        tiles: Array.isArray(source.tiles) ? source.tiles : [],
      });
    }
  }
  if (pool.length < 1) throw new ApiError("ما كايناش أسئلة فالأنواع المختارة.", 400, "not_enough_questions");
  if (!wholeExercises && requestedCount > pool.length) {
    throw new ApiError(`هاد الأنواع فيها ${pool.length} أسئلة مختلفة فقط. نقص عدد الأسئلة.`, 400, "question_count_exceeds_pool");
  }
  // In complete-Übung mode, every chosen exercise is a single visual stage.
  // But answers and points are still handled individually using the existing secure RPC.
  const selected = wholeExercises ? pool : shuffle(pool).slice(0, requestedCount);
  const questions: any[] = [];
  const correctIndices: number[] = [];
  for (const item of selected) {
    // Keep original choice order when showing the complete original exercise.
    const choices = wholeExercises
      ? item.options.map((label: string, i: number) => ({label, isCorrect: i === item.correctIndex}))
      : shuffle(item.options.map((label: string, i: number) => ({label, isCorrect: i === item.correctIndex})));
    const question: any = {
      prompt: item.prompt,
      options: choices.map((choice: any) => choice.label),
      lessonIndex: item.lessonIndex,
      lessonName: item.lessonName,
      category: item.category,
      level,
    };
    if (wholeExercises) {
      question.groupId = `${item.lessonIndex}|${item.category}`;
      question.groupTitle = item.exerciseTitle || item.category.replace(/^Zusatztest\s*·\s*/, "").replace(/^L7 A1\.1\s*·\s*/, "");
      question.exerciseNumber = Number(item.exerciseNumber) || null;
      question.exerciseType = item.exerciseType || "choice";
      question.answerMode = item.answerMode || "choice";
      const invalidIndex = choices.findIndex((choice: any) => !choice.isCorrect);
      question.invalidIndex = invalidIndex >= 0 ? invalidIndex : 0;
      if (item.exerciseInstruction) question.exerciseInstruction = item.exerciseInstruction;
      if (item.note) question.note = item.note;
      if (item.scramble) question.scramble = item.scramble;
      if (Array.isArray(item.letters)) question.letters = item.letters;
      if (Array.isArray(item.tiles)) question.tiles = item.tiles;
    }
    questions.push(question);
    correctIndices.push(choices.findIndex((choice: any) => choice.isCorrect));
  }
  return { questions, correctIndices };
}
function newCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  const bytes = crypto.getRandomValues(new Uint8Array(6));
  return Array.from(bytes, (b) => chars[b % chars.length]).join("");
}
function safeRoom(room: any, members: any[], viewerUid: string) {
  return {
    id: room.id, code: room.code, createdBy: room.created_by,
    // Derived on the server from the verified Firebase token, never client input.
    isCreator: room.created_by === viewerUid, creatorName: room.creator_name,
    mode: room.mode, status: room.status, level: normalizeCompetitionLevel(room.questions?.[0]?.level || "A1"),
    lessonIndices: room.lesson_indices, lessonNames: room.lesson_names,
    questionCount: room.question_count, questions: room.questions, createdAt: room.created_at,
    startedAt: room.started_at, completedAt: room.completed_at,
    members: Object.fromEntries(members.map((m) => [m.uid, {
      uid: m.uid, name: m.name, score: m.score, answeredCount: m.answered_count,
      correctCount: m.correct_count, finished: m.finished, joinedAt: m.joined_at,
    }])),
  };
}
function dbClient() {
  if (!supabase) throw new ApiError("Supabase service key ما متوفرش داخل Edge Function. راجع Secrets.", 500, "missing_server_key");
  return supabase;
}
function normalizeSelfTestTypes(lessonIndices: number[], rawTypes: any) {
  const source = rawTypes && typeof rawTypes === "object" && !Array.isArray(rawTypes) ? rawTypes : {};
  return Object.fromEntries(lessonIndices.map((index) => [
    String(index),
    [...new Set<number>((Array.isArray(source[String(index)]) ? source[String(index)] : []).map(Number)
      .filter((value: number) => Number.isInteger(value) && value >= 0))].sort((a, b) => a - b),
  ]));
}
async function selfChallengeKey(level: string, lessonIndices: number[], testTypes: Record<string, number[]>, wholeExercises: boolean, questionCount: number) {
  const payload = JSON.stringify({
    ...(level === "A2" ? { level } : {}),
    lessonIndices: lessonIndices.slice().sort((a, b) => a - b),
    testTypes: Object.fromEntries(Object.keys(testTypes).sort().map((key) => [key, testTypes[key]])),
    wholeExercises: Boolean(wholeExercises), questionCount: Number(questionCount),
  });
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(payload));
  return Array.from(new Uint8Array(digest)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}
function safePersonalRecord(row: any) {
  if (!row) return null;
  return {
    challengeKey: row.challenge_key,
    lessonIndices: row.lesson_indices || [],
    lessonNames: row.lesson_names || [],
    questionCount: Number(row.question_count) || Number(row.total_questions) || 0,
    bestScore: Number(row.best_score) || 0,
    bestCorrectCount: Number(row.best_correct_count) || 0,
    totalQuestions: Number(row.total_questions) || 0,
    attempts: Number(row.attempts) || 0,
    lastScore: Number(row.last_score) || 0,
    lastCorrectCount: Number(row.last_correct_count) || 0,
    updatedAt: row.updated_at || null,
  };
}
function safeSelfChallenge(row: any, personalRecord: any = null) {
  return {
    id: row.id,
    level: normalizeCompetitionLevel(row.questions?.[0]?.level || "A1"),
    challengeKey: row.challenge_key,
    lessonIndices: row.lesson_indices || [],
    lessonNames: row.lesson_names || [],
    testTypes: row.test_types || {},
    wholeExercises: row.whole_exercises === true,
    questionCount: Number(row.question_count) || 0,
    questions: row.questions || [],
    score: Number(row.score) || 0,
    correctCount: Number(row.correct_count) || 0,
    answeredCount: Number(row.answered_count) || 0,
    previousBestScore: Number(row.previous_best_score) || 0,
    status: row.status,
    createdAt: row.created_at || null,
    completedAt: row.completed_at || null,
    personalRecord: safePersonalRecord(personalRecord),
  };
}
async function readSelfPersonalRecord(uid: string, challengeKey: string) {
  const { data, error } = await dbClient().from("competition_personal_records")
    .select("uid,challenge_key,lesson_indices,lesson_names,question_count,best_score,best_correct_count,total_questions,attempts,last_score,last_correct_count,updated_at")
    .eq("uid", uid).eq("challenge_key", challengeKey).maybeSingle();
  if (error) throw new ApiError(error.message, 500, "personal_record_read_failed");
  return data;
}
async function saveSelfPersonalRecord(challenge: any, score: number, correctCount: number) {
  const existing = await readSelfPersonalRecord(challenge.uid, challenge.challenge_key);
  const oldBest = Number(existing?.best_score) || 0;
  const newBest = Math.max(oldBest, score);
  const bestCorrect = score > oldBest
    ? correctCount
    : score === oldBest ? Math.max(Number(existing?.best_correct_count) || 0, correctCount)
    : Number(existing?.best_correct_count) || 0;
  const payload = {
    uid: challenge.uid,
    challenge_key: challenge.challenge_key,
    lesson_indices: challenge.lesson_indices || [],
    lesson_names: challenge.lesson_names || [],
    test_types: challenge.test_types || {},
    whole_exercises: challenge.whole_exercises === true,
    question_count: Number(challenge.question_count) || 0,
    best_score: newBest,
    best_correct_count: bestCorrect,
    total_questions: Number(challenge.question_count) || 0,
    attempts: (Number(existing?.attempts) || 0) + 1,
    last_score: score,
    last_correct_count: correctCount,
    updated_at: new Date().toISOString(),
  };
  const { data, error } = await dbClient().from("competition_personal_records")
    .upsert(payload, { onConflict: "uid,challenge_key" })
    .select("uid,challenge_key,lesson_indices,lesson_names,question_count,best_score,best_correct_count,total_questions,attempts,last_score,last_correct_count,updated_at")
    .single();
  if (error) throw new ApiError(error.message, 500, "personal_record_save_failed");
  return data;
}
async function handleAction(action: string, body: any, identity: any) {
  const uid = identity.uid;
  if (action === "getCompetitionAccess") {
    const profile = await getStudentProfile(uid, identity.token);
    const group = profile.groupId ? await firebaseRead(`deutschA1/groups/${encodeURIComponent(String(profile.groupId))}`, identity.token) : null;
    const levels = Object.fromEntries(["A1", "A2", "B1", "B2"].map(level => [level, {
      allowed: competitionLevelPermitted(profile, group, level),
      lessons: ["A1", "A2"].includes(level) ? competitionBankForLevel(level).map((_: any, index: number) => competitionLessonPermitted(profile, group, index, level)) : [],
    }]));
    return { levels, groupId: profile.groupId || "", groupName: group?.name || "" };
  }
  if (action === "createCompetitionRoom") {
    console.info("competition create: validating authenticated student");
    const profile = await getStudentProfile(uid, identity.token);
    const competitionLevel = normalizeCompetitionLevel(body.level);
    await assertCompetitionLevelAccess(profile, identity.token, competitionLevel);
    const bank = competitionBankForLevel(competitionLevel);
    const lessonIndices: number[] = Array.isArray(body.lessonIndices) ? [...new Set<number>((body.lessonIndices as unknown[]).map((n) => Number(n)).filter((n) => Number.isInteger(n) && n >= 0 && n < bank.length))] : [];
    const questionCount = Number(body.questionCount); const mode = body.mode === "group" ? "group" : "duel";
    if (!lessonIndices.length || lessonIndices.length > bank.length || lessonIndices.some((index) => !bank[index]?.questions?.length)) throw new ApiError("اختار درساً فيه أسئلة متاحة على الأقل.", 400);
    if (!Number.isInteger(questionCount) || questionCount < 1 || questionCount > 1000) {
      throw new ApiError("عدد الأسئلة لازم يكون بين 1 و 1000.", 400, "invalid_question_count");
    }
    await assertLessonAccess(profile, identity.token, lessonIndices, competitionLevel);
    const quiz = buildQuiz(competitionLevel, lessonIndices, questionCount, body.testTypes, body.wholeExercises === true);
    console.info("competition create: quiz ready", { level: competitionLevel, questionCount: quiz.questions.length, lessons: lessonIndices.length });
    const lessonNames = lessonIndices.map((i) => bank[i]?.name || `L${i + 1}`);
    for (let attempt = 0; attempt < 12; attempt++) {
      const code = newCode();
      const { data, error } = await dbClient().rpc("competition_create_room", {
        p_code: code, p_created_by: uid, p_creator_name: cleanName(profile.name, identity.claims.name),
        p_mode: mode, p_lesson_indices: lessonIndices, p_lesson_names: lessonNames,
        p_question_count: quiz.questions.length, p_questions: quiz.questions, p_correct_indices: quiz.correctIndices,
      });
      if (!error && data) {
        console.info("competition create: room saved successfully");
        return { roomId: data, code };
      }
      if (error?.code === "23505") continue;
      console.error("competition_create_room:", error);
      throw new ApiError(error?.message || "تعذّر إنشاء غرفة المنافسة.", 500, "create_failed");
    }
    throw new ApiError("ما قدرناش نولدو رمز فريد. حاول مرة أخرى.", 503, "code_generation_failed");
  }
  if (action === "createSelfChallenge") {
    const profile = await getStudentProfile(uid, identity.token);
    const competitionLevel = normalizeCompetitionLevel(body.level);
    await assertCompetitionLevelAccess(profile, identity.token, competitionLevel);
    const bank = competitionBankForLevel(competitionLevel);
    const lessonIndices: number[] = Array.isArray(body.lessonIndices)
      ? [...new Set<number>((body.lessonIndices as unknown[]).map(Number).filter((n) => Number.isInteger(n) && n >= 0 && n < bank.length))]
      : [];
    const requestedCount = Number(body.questionCount);
    const wholeExercises = body.wholeExercises === true;
    if (!lessonIndices.length || lessonIndices.length > bank.length || lessonIndices.some((index) => !bank[index]?.questions?.length)) throw new ApiError("اختار درساً فيه أسئلة متاحة على الأقل.", 400);
    if (!Number.isInteger(requestedCount) || requestedCount < 1 || requestedCount > 1000) {
      throw new ApiError("عدد الأسئلة لازم يكون بين 1 و 1000.", 400, "invalid_question_count");
    }
    await assertLessonAccess(profile, identity.token, lessonIndices, competitionLevel);
    const testTypes = normalizeSelfTestTypes(lessonIndices, body.testTypes);
    const quiz = buildQuiz(competitionLevel, lessonIndices, requestedCount, testTypes, wholeExercises);
    const lessonNames = lessonIndices.map((index) => bank[index]?.name || `L${index + 1}`);
    const questionCount = quiz.questions.length;
    const challengeKey = await selfChallengeKey(competitionLevel, lessonIndices, testTypes, wholeExercises, questionCount);
    const previousRecord = await readSelfPersonalRecord(uid, challengeKey);
    const { data: row, error } = await dbClient().from("competition_self_challenges").insert({
      uid, challenge_key: challengeKey, lesson_indices: lessonIndices, lesson_names: lessonNames,
      test_types: testTypes, whole_exercises: wholeExercises, question_count: questionCount,
      questions: quiz.questions, correct_indices: quiz.correctIndices,
      previous_best_score: Number(previousRecord?.best_score) || 0,
      score: 0, correct_count: 0, answered_count: 0, status: "active",
    }).select("*").single();
    if (error) throw new ApiError(error.message, 500, "self_challenge_create_failed");
    return { challenge: safeSelfChallenge(row, previousRecord) };
  }
  if (action === "getSelfChallenge") {
    const profile = await getStudentProfile(uid, identity.token);
    const challengeId = String(body.challengeId || "");
    if (!challengeId) throw new ApiError("معرّف التحدي غير صالح.", 400);
    const { data: row, error } = await dbClient().from("competition_self_challenges")
      .select("*").eq("id", challengeId).eq("uid", uid).maybeSingle();
    if (error) throw new ApiError(error.message, 500, "self_challenge_read_failed");
    if (!row) throw new ApiError("هاد التحدي ما بقاش متاح.", 404, "self_challenge_not_found");
    const challengeLevel = normalizeCompetitionLevel(row.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, challengeLevel);
    await assertLessonAccess(profile, identity.token, row.lesson_indices || [], challengeLevel);
    const personalRecord = await readSelfPersonalRecord(uid, row.challenge_key);
    return { challenge: safeSelfChallenge(row, personalRecord) };
  }
  if (action === "submitSelfChallengeAnswer") {
    const profile = await getStudentProfile(uid, identity.token);
    const challengeId = String(body.challengeId || "");
    const questionIndex = Number(body.questionIndex);
    const selectedIndex = Number(body.selectedIndex);
    if (!challengeId || !Number.isInteger(questionIndex) || !Number.isInteger(selectedIndex)) {
      throw new ApiError("الجواب المرسل غير صالح.", 400, "invalid_self_answer");
    }
    const { data: row, error: readError } = await dbClient().from("competition_self_challenges")
      .select("*").eq("id", challengeId).eq("uid", uid).maybeSingle();
    if (readError) throw new ApiError(readError.message, 500, "self_challenge_read_failed");
    if (!row) throw new ApiError("هاد التحدي ما بقاش متاح.", 404, "self_challenge_not_found");
    const challengeLevel = normalizeCompetitionLevel(row.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, challengeLevel);
    await assertLessonAccess(profile, identity.token, row.lesson_indices || [], challengeLevel);
    if (row.status !== "active") throw new ApiError("هاد التحدي تسالى بالفعل.", 409, "self_challenge_finished");
    const questions = Array.isArray(row.questions) ? row.questions : [];
    const correctIndices = Array.isArray(row.correct_indices) ? row.correct_indices : [];
    if (questionIndex !== Number(row.answered_count) || questionIndex < 0 || questionIndex >= questions.length) {
      throw new ApiError("هاد السؤال تسجّل من قبل أو ماشي هو السؤال الحالي.", 409, "self_question_out_of_order");
    }
    const options = Array.isArray(questions[questionIndex]?.options) ? questions[questionIndex].options : [];
    if (selectedIndex < 0 || selectedIndex >= options.length) throw new ApiError("اختيار الجواب غير صالح.", 400, "invalid_self_option");
    const correct = selectedIndex === Number(correctIndices[questionIndex]);
    const pointsAwarded = correct ? 10 : 0;
    const score = (Number(row.score) || 0) + pointsAwarded;
    const correctCount = (Number(row.correct_count) || 0) + (correct ? 1 : 0);
    const answeredCount = (Number(row.answered_count) || 0) + 1;
    const finished = answeredCount >= questions.length;
    const updates: any = { score, correct_count: correctCount, answered_count: answeredCount };
    if (finished) { updates.status = "completed"; updates.completed_at = new Date().toISOString(); }
    const { data: updated, error: updateError } = await dbClient().from("competition_self_challenges")
      .update(updates).eq("id", challengeId).eq("uid", uid).eq("status", "active")
      .eq("answered_count", Number(row.answered_count))
      .select("*").single();
    if (updateError) throw new ApiError(updateError.message, 409, "self_answer_save_failed");
    let personalRecord = null;
    if (finished) personalRecord = await saveSelfPersonalRecord(updated, score, correctCount);
    return {
      correct, pointsAwarded, score, correctCount, answeredCount, finished,
      previousBestScore: Number(updated.previous_best_score) || 0,
      personalRecord: safePersonalRecord(personalRecord),
    };
  }
  if (action === "abandonSelfChallenge") {
    const challengeId = String(body.challengeId || "");
    if (!challengeId) throw new ApiError("معرّف التحدي غير صالح.", 400);
    const { error } = await dbClient().from("competition_self_challenges")
      .update({ status: "abandoned" }).eq("id", challengeId).eq("uid", uid).eq("status", "active");
    if (error) throw new ApiError(error.message, 500, "self_challenge_abandon_failed");
    return { success: true };
  }
  if (action === "joinCompetitionRoom") {
    const profile = await getStudentProfile(uid, identity.token);
    const code = String(body.code || "").trim().toUpperCase();
    if (!/^[A-Z0-9]{6}$/.test(code)) throw new ApiError("رمز المنافسة غير صالح.", 400);
    const { data: room, error } = await dbClient().from("competition_rooms").select("id,lesson_indices,questions").eq("code", code).maybeSingle();
    if (error) throw new ApiError(error.message, 500, "database_error");
    if (!room) throw new ApiError("ما لقيناش غرفة بهاد الرمز.", 404, "room_not_found");
    const roomLevel = normalizeCompetitionLevel(room.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, roomLevel);
    await assertLessonAccess(profile, identity.token, room.lesson_indices || [], roomLevel);
    const { error: joinError } = await dbClient().rpc("competition_join_room", { p_room_id: room.id, p_uid: uid, p_name: cleanName(profile.name, identity.claims.name) });
    if (joinError) throw new ApiError(joinError.message, 409, joinError.code || "join_failed");
    // Joining never starts a match. Only the room creator may press Start.
    return { roomId: room.id };
  }
  if (action === "startCompetitionRoom") {
    const profile = await getStudentProfile(uid, identity.token);
    // Server-side authorization: only the authenticated creator may start
    // and at least two participants must already have joined.
    const roomId = String(body.roomId || "");
    const { data: room, error: roomError } = await dbClient().from("competition_rooms")
      .select("id,created_by,status,lesson_indices,questions").eq("id", roomId).maybeSingle();
    if (roomError) throw new ApiError(roomError.message, 500, "database_error");
    if (!room) throw new ApiError("الغرفة ما بقاتش متاحة.", 404, "room_not_found");
    const roomLevel = normalizeCompetitionLevel(room.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, roomLevel);
    await assertLessonAccess(profile, identity.token, room.lesson_indices || [], roomLevel);
    if (room.created_by !== uid) throw new ApiError("غير صاحب الغرفة اللي يقدر يبدأ المنافسة.", 403, "creator_only");
    if (room.status !== "waiting") throw new ApiError("المنافسة بدات بالفعل أو سالات.", 409, "not_waiting");
    const { count, error: membersError } = await dbClient().from("competition_members")
      .select("uid", { count: "exact", head: true }).eq("room_id", roomId);
    if (membersError) throw new ApiError(membersError.message, 500, "database_error");
    if ((count ?? 0) < 2) throw new ApiError("خاص جوج لاعبين على الأقل باش تبدا المنافسة.", 409, "not_enough_players");
    const { error } = await dbClient().rpc("competition_start_room", { p_room_id: roomId, p_uid: uid });
    if (error) throw new ApiError(error.message, 409, error.code || "start_failed");
    return { success: true };
  }
  if (action === "submitCompetitionAnswer") {
    const profile = await getStudentProfile(uid, identity.token);
    const roomId = String(body.roomId || "");
    const { data: room, error: roomReadError } = await dbClient().from("competition_rooms")
      .select("id,lesson_indices,questions").eq("id", roomId).maybeSingle();
    if (roomReadError) throw new ApiError(roomReadError.message, 500, "database_error");
    if (!room) throw new ApiError("الغرفة ما بقاتش متاحة.", 404, "room_not_found");
    const roomLevel = normalizeCompetitionLevel(room.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, roomLevel);
    await assertLessonAccess(profile, identity.token, room.lesson_indices || [], roomLevel);
    const { data, error } = await dbClient().rpc("competition_submit_answer", { p_room_id: roomId, p_uid: uid, p_question_index: Number(body.questionIndex), p_selected_index: Number(body.selectedIndex) });
    if (error) throw new ApiError(error.message, 409, error.code || "answer_failed"); return data;
  }
  if (action === "finishCompetitionRoom") {
    const profile = await getStudentProfile(uid, identity.token);
    const roomId = String(body.roomId || "");
    const { data: room, error: roomReadError } = await dbClient().from("competition_rooms")
      .select("id,lesson_indices,questions").eq("id", roomId).maybeSingle();
    if (roomReadError) throw new ApiError(roomReadError.message, 500, "database_error");
    if (!room) throw new ApiError("الغرفة ما بقاتش متاحة.", 404, "room_not_found");
    const roomLevel = normalizeCompetitionLevel(room.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, roomLevel);
    await assertLessonAccess(profile, identity.token, room.lesson_indices || [], roomLevel);
    const { error } = await dbClient().rpc("competition_finish_member", { p_room_id: roomId, p_uid: uid });
    if (error) throw new ApiError(error.message, 409, error.code || "finish_failed"); return { success: true };
  }
  if (action === "leaveCompetitionRoom") {
    const { error } = await dbClient().rpc("competition_leave_room", { p_room_id: body.roomId, p_uid: uid });
    if (error) throw new ApiError(error.message, 409, error.code || "leave_failed"); return { success: true };
  }
  if (action === "getCompetitionRoom") {
    const profile = await getStudentProfile(uid, identity.token);
    const roomId = String(body.roomId || "");
    const { data: room, error } = await dbClient().from("competition_rooms").select("id,code,created_by,creator_name,mode,status,lesson_indices,lesson_names,question_count,questions,created_at,started_at,completed_at").eq("id", roomId).maybeSingle();
    if (error) throw new ApiError(error.message, 500, "database_error");
    if (!room) throw new ApiError("الغرفة ما بقاتش متاحة.", 404, "room_not_found");
    const roomLevel = normalizeCompetitionLevel(room.questions?.[0]?.level || "A1");
    await assertCompetitionLevelAccess(profile, identity.token, roomLevel);
    await assertLessonAccess(profile, identity.token, room.lesson_indices || [], roomLevel);
    const { data: members, error: memberError } = await dbClient().from("competition_members").select("uid,name,score,answered_count,correct_count,finished,joined_at").eq("room_id", roomId);
    if (memberError) throw new ApiError(memberError.message, 500, "database_error");
    if (!(members || []).some((m: any) => m.uid === uid)) throw new ApiError("ماشي عضو فهاد المنافسة.", 403, "not_a_member");
    return { room: safeRoom(room, members || [], uid) };
  }
  if (action === "getCompetitionStats") {
    const { data, error } = await dbClient().from("competition_stats").select("uid,name,total_points,competitions_played,wins").order("total_points", { ascending: false }).limit(50);
    if (error) throw new ApiError(error.message, 500, "database_error");
    let personalRecords: any[] = [];
    const { data: records, error: recordsError } = await dbClient().from("competition_personal_records")
      .select("uid,challenge_key,lesson_indices,lesson_names,question_count,best_score,best_correct_count,total_questions,attempts,last_score,last_correct_count,updated_at")
      .eq("uid", uid).order("updated_at", { ascending: false }).limit(12);
    if (recordsError) {
      // Keep the existing multiplayer leaderboard available if the migration
      // has not been applied yet; self-competition itself requires the tables.
      console.warn("Personal competition records unavailable:", recordsError.message);
    } else personalRecords = (records || []).map(safePersonalRecord);
    return {
      stats: (data || []).map((x: any) => ({ uid: x.uid, name: x.name, totalPoints: x.total_points, competitionsPlayed: x.competitions_played, wins: x.wins })),
      personalRecords,
    };
  }
  throw new ApiError("طلب غير معروف.", 404, "unknown_action");
}
Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);
  try {
    if (!SUPABASE_URL || !SERVICE_ROLE_KEY) throw new ApiError("مفتاح الخدمة ديال Supabase غير متوفر داخل Edge Function. راجع Secrets.", 500, "server_not_configured");
    const identity = await getIdentity(req);
    const body = await req.json().catch(() => ({}));
    return json({ data: await handleAction(String(body.action || ""), body, identity) });
  } catch (error) {
    const apiError = error instanceof ApiError ? error : new ApiError("وقع خطأ داخلي فخدمة المنافسة.", 500, "internal");
    console.error("competition edge function:", error);
    return json({ error: apiError.message, code: apiError.code }, apiError.status);
  }
});
